// Extract brief content from Notion page
const response = $input.first().json;
const results = response.results || [];

if (results.length === 0) {
  return [{ json: { empty: true, message: 'No research brief found' } }];
}

const page = results[0];
const title = page.properties?.Title?.title?.[0]?.text?.content || 'Untitled Brief';
const pageId = page.id;

// We'll need to fetch the page blocks for the actual brief content
return [{
  json: {
    pageId,
    title,
    empty: false
  }
}];

// Reconstruct brief text from Notion blocks
const response = $input.first().json;
const blocks = response.results || [];
let briefText = '';

for (const block of blocks) {
  if (block.type === 'paragraph' && block.paragraph?.rich_text) {
    briefText += block.paragraph.rich_text.map(t => t.text?.content || '').join('') + '\n\n';
  } else if (block.type === 'heading_1' && block.heading_1?.rich_text) {
    briefText += '# ' + block.heading_1.rich_text.map(t => t.text?.content || '').join('') + '\n\n';
  } else if (block.type === 'heading_2' && block.heading_2?.rich_text) {
    briefText += '## ' + block.heading_2.rich_text.map(t => t.text?.content || '').join('') + '\n\n';
  } else if (block.type === 'heading_3' && block.heading_3?.rich_text) {
    briefText += '### ' + block.heading_3.rich_text.map(t => t.text?.content || '').join('') + '\n\n';
  } else if (block.type === 'bulleted_list_item' && block.bulleted_list_item?.rich_text) {
    briefText += '• ' + block.bulleted_list_item.rich_text.map(t => t.text?.content || '').join('') + '\n';
  }
}

return [{ json: { briefText: briefText.trim() } }];

// Parse Claude's response into 3 separate tier drafts
const response = $input.first().json;
let fullText = '';

if (response.content && Array.isArray(response.content)) {
  fullText = response.content
    .filter(c => c.type === 'text')
    .map(c => c.text)
    .join('');
}

const today = new Date();
const dateStr = today.toISOString().split('T')[0];
const weekNumber = Math.ceil((today - new Date(today.getFullYear(), 0, 1)) / (7 * 24 * 60 * 60 * 1000));

// Parse out each tier
function extractTier(text, startTag, endTag) {
  const startIdx = text.indexOf(startTag);
  const endIdx = text.indexOf(endTag);
  if (startIdx === -1 || endIdx === -1) return 'PARSE ERROR: Tier not found in Claude response';
  return text.substring(startIdx + startTag.length, endIdx).trim();
}

const tier1 = extractTier(fullText, '---TIER1_EXEC_START---', '---TIER1_EXEC_END---');
const tier2 = extractTier(fullText, '---TIER2_TECH_START---', '---TIER2_TECH_END---');
const tier3 = extractTier(fullText, '---TIER3_BUILDER_START---', '---TIER3_BUILDER_END---');

return [
  { json: { tier: 'tier1_exec', title: `The Prompt — Executive Edition (W${weekNumber})`, content: tier1, date: dateStr, week: weekNumber } },
  { json: { tier: 'tier2_tech', title: `The Prompt — Technical Edition (W${weekNumber})`, content: tier2, date: dateStr, week: weekNumber } },
  { json: { tier: 'tier3_builder', title: `The Prompt — Builder Edition (W${weekNumber})`, content: tier3, date: dateStr, week: weekNumber } }
];

// Build summary of all drafts created
const items = $input.all();
const drafts = items.map(i => `• ${i.json.tier}: Draft saved`).join('\n');

return [{
  json: {
    text: `✍️ *Newsletter Drafts Generated*\n\n${drafts}\n\n→ Review and edit in Notion Newsletter Drafts\n→ When ready, publish via Substack`
  }
}];
